-- Own validator preserves authored whitespace and Unicode; published normalizers remain untouched.
CREATE FUNCTION firstten_private.guest_growth_field(v jsonb,s jsonb)RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE k text;x jsonb;r jsonb;t text;f text;n numeric;
BEGIN
 IF v IS NULL OR s IS NULL THEN RAISE EXCEPTION 'Invalid growth field' USING ERRCODE='22023';END IF;
 IF v='null'::jsonb AND coalesce((s->>'nullable')::boolean,false)THEN RETURN v;END IF;
 IF s?'const'THEN IF v<>s->'const'THEN RAISE EXCEPTION 'Invalid growth constant' USING ERRCODE='22023';END IF;RETURN v;END IF;
 IF s?'discriminator'THEN RETURN firstten_private.guest_growth_field(v,s->'variants'->(v->>(s->>'discriminator')));END IF;
 IF s->>'type'='object'THEN
  IF jsonb_typeof(v)<>'object'OR(SELECT count(*)FROM jsonb_object_keys(v))<>(SELECT count(*)FROM jsonb_object_keys(s->'properties'))THEN RAISE EXCEPTION 'Invalid growth object' USING ERRCODE='22023';END IF;
  r:='{}';FOR k,x IN SELECT key,value FROM jsonb_each(s->'properties')LOOP r:=r||jsonb_build_object(k,firstten_private.guest_growth_field(v->k,x));END LOOP;RETURN r;
 ELSIF s->>'type'='array'THEN
  IF jsonb_typeof(v)<>'array'OR jsonb_array_length(v)>(s->>'maxItems')::int OR jsonb_array_length(v)<coalesce((s->>'minItems')::int,0)THEN RAISE EXCEPTION 'Invalid growth array' USING ERRCODE='22023';END IF;
  r:='[]';FOR x IN SELECT value FROM jsonb_array_elements(v)LOOP r:=r||jsonb_build_array(firstten_private.guest_growth_field(x,s->'items'));END LOOP;RETURN r;
 ELSIF s->>'type'='integer'THEN
  IF jsonb_typeof(v)<>'number'THEN RAISE EXCEPTION 'Invalid growth integer' USING ERRCODE='22023';END IF;n:=(v::text)::numeric;
  IF n<>trunc(n)OR(s?'enum'AND NOT s->'enum'@>jsonb_build_array(v))OR(s?'minimum'AND n<(s->>'minimum')::numeric)OR(s?'maximum'AND n>(s->>'maximum')::numeric)THEN RAISE EXCEPTION 'Invalid growth integer bounds' USING ERRCODE='22023';END IF;RETURN to_jsonb(n::bigint);
 END IF;
 IF jsonb_typeof(v)<>'string'THEN RAISE EXCEPTION 'Invalid growth text' USING ERRCODE='22023';END IF;t:=v#>>'{}';f:=s->>'format';
 IF(s?'maxLength'AND char_length(t)>(s->>'maxLength')::int)OR(s?'enum'AND NOT s->'enum'?t)THEN RAISE EXCEPTION 'Invalid growth text bounds' USING ERRCODE='22023';END IF;
 IF f='uuid'THEN IF t!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'THEN RAISE EXCEPTION 'Invalid growth UUID' USING ERRCODE='22023';END IF;RETURN to_jsonb(lower(t));
 ELSIF f IN('day','instant')THEN
  IF t!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}'OR left(t,4)='0000'OR to_char(make_date(left(t,4)::int,substring(t,6,2)::int,substring(t,9,2)::int),'YYYY-MM-DD')<>left(t,10)
   OR(f='day'AND length(t)<>10)OR(f='instant'AND t!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](\.[0-9]+)?(Z|[+-]([01][0-9]|2[0-3]):?[0-5][0-9])$')THEN RAISE EXCEPTION 'Invalid growth date' USING ERRCODE='22023';END IF;
 END IF;RETURN v;
END $$;
-- Compact serialization matches JS JSON.stringify byte accounting (order never changes byte count).
CREATE FUNCTION firstten_private.guest_growth_json(v jsonb)RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE r text;
BEGIN
 IF jsonb_typeof(v)='object'THEN SELECT '{'||coalesce(string_agg(to_jsonb(key)::text||':'||firstten_private.guest_growth_json(value),',' ORDER BY key COLLATE "C"),'')||'}'INTO r FROM jsonb_each(v);
 ELSIF jsonb_typeof(v)='array'THEN SELECT '['||coalesce(string_agg(firstten_private.guest_growth_json(value),',' ORDER BY n),'')||']'INTO r FROM jsonb_array_elements(v)WITH ORDINALITY x(value,n);
 ELSE r:=v::text;END IF;RETURN r;
END $$;
-- Fixed UTF8 prerequisite above makes this exact canonical digest immutable. PL/pgSQL prevents SQL inlining.
CREATE FUNCTION firstten_private.guest_growth_hash(v jsonb)RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$BEGIN RETURN encode(sha256(convert_to(firstten_private.guest_growth_json(v),'UTF8')),'hex');END $$;
CREATE FUNCTION firstten_private.guest_growth_trim(t text)RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT btrim(t,U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF')$$;
CREATE FUNCTION firstten_private.guest_growth_refs(d jsonb)RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
SELECT CASE d->>'kind'WHEN'experiment'THEN d->'learningRefs'WHEN'survey'THEN CASE WHEN d->'experimentRef'='null'::jsonb THEN'[]'::jsonb ELSE jsonb_build_array(d->'experimentRef')END
WHEN'onboarding'THEN CASE WHEN d->'experimentRef'='null'::jsonb THEN'[]'::jsonb ELSE jsonb_build_array(d->'experimentRef')END
WHEN'referral'THEN(SELECT coalesce(jsonb_agg(x),'[]'::jsonb)FROM(VALUES(d->'contactRef'),(d->'experimentRef'))v(x)WHERE x<>'null'::jsonb)ELSE'[]'::jsonb END$$;
