CREATE FUNCTION firstten_private.guest_growth_case_range(n integer,ranges jsonb)RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE lo integer:=0;hi integer:=jsonb_array_length(ranges)-1;mid integer;r jsonb;
BEGIN IF n IS NULL THEN RETURN false;END IF;WHILE lo<=hi LOOP mid:=(lo+hi)/2;r:=ranges->mid;IF n<(r->>0)::integer THEN hi:=mid-1;ELSIF n>(r->>1)::integer THEN lo:=mid+1;ELSE RETURN true;END IF;END LOOP;RETURN false;END $$;
CREATE FUNCTION firstten_private.guest_growth_option_key(t text)RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE data jsonb:=firstten_private.guest_growth_option_case_data();chars text[];i integer;l integer;r integer;n integer;result text:='';before_cased boolean;after_cased boolean;
BEGIN
 t:=firstten_private.guest_growth_trim(t);IF char_length(t)>120 THEN RAISE EXCEPTION 'Option exceeds closed bound' USING ERRCODE='22023';END IF;
 chars:=string_to_array(t,NULL);FOR i IN 1..coalesce(cardinality(chars),0)LOOP n:=ascii(chars[i]);
  IF n=931 THEN l:=i-1;r:=i+1;
   WHILE l>=1 AND firstten_private.guest_growth_case_range(ascii(chars[l]),data->'ignorable')LOOP l:=l-1;END LOOP;
   WHILE r<=cardinality(chars)AND firstten_private.guest_growth_case_range(ascii(chars[r]),data->'ignorable')LOOP r:=r+1;END LOOP;
   before_cased:=l>=1 AND firstten_private.guest_growth_case_range(ascii(chars[l]),data->'cased');after_cased:=r<=cardinality(chars)AND firstten_private.guest_growth_case_range(ascii(chars[r]),data->'cased');
   result:=result||CASE WHEN before_cased AND NOT after_cased THEN'ς'ELSE'σ'END;
  ELSE result:=result||coalesce(data->'lower'->>n::text,chars[i]);END IF;
 END LOOP;RETURN result;
END $$;
CREATE FUNCTION firstten_private.normalize_guest_growth(doc jsonb)RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE d jsonb;q jsonb;refs jsonb;a text;k text;
BEGIN
 IF doc IS NULL OR octet_length(doc::text)>65536 THEN RAISE EXCEPTION 'Invalid growth size' USING ERRCODE='22023';END IF;
 d:=firstten_private.guest_growth_field(doc,firstten_private.guest_growth_shapes()->(doc->>'kind'));k:=d->>'kind';
 IF octet_length(firstten_private.guest_growth_json(d))>32768 OR d::text~*'-----BEGIN [A-Z ]*PRIVATE KEY-----|(sk|ghp|github_pat|xox[baprs])[-_][A-Za-z0-9_-]{12,}|Bearer [A-Za-z0-9._-]{16,}|(^|[^A-Za-z0-9_])[a-f0-9]{64}([^A-Za-z0-9_]|$)'THEN RAISE EXCEPTION 'Invalid growth content' USING ERRCODE='22023';END IF;
 IF k='learning'AND((d->>'reviewState'='draft'AND d->'reviewedAt'<>'null'::jsonb)OR(d->>'reviewState'='reviewed'AND(d->'reviewedAt'='null'::jsonb OR firstten_private.guest_growth_trim(d->>'title')=''OR firstten_private.guest_growth_trim(d->>'interpretation')=''OR firstten_private.guest_growth_trim(d->>'nextTest')='')))THEN RAISE EXCEPTION 'Invalid reported review' USING ERRCODE='22023';END IF;
 IF k='experiment'THEN
  IF(d->>'state'='planned'AND(d->'reportedStartOn'<>'null'::jsonb OR d->'reportedResult'<>firstten_private.guest_growth_blank(k)->'reportedResult'))
   OR(d->>'state'<>'planned'AND d->'reportedStartOn'='null'::jsonb)
   OR(d->>'state'IN('completed_reported','stopped_reported')AND(d#>'{reportedResult,reportedOn}'='null'::jsonb OR firstten_private.guest_growth_trim(d#>>'{reportedResult,summary}')=''OR firstten_private.guest_growth_trim(d#>>'{reportedResult,limitations}')=''))
   OR(d->'reportedStartOn'<>'null'::jsonb AND d#>'{reportedResult,reportedOn}'<>'null'::jsonb AND d->>'reportedStartOn'>d#>>'{reportedResult,reportedOn}')THEN RAISE EXCEPTION 'Invalid reported test result' USING ERRCODE='22023';END IF;
 END IF;
 IF k IN('pipeline_contact','referral')THEN a:=CASE k WHEN'pipeline_contact'THEN d->>'alias'ELSE d->>'recipientAlias'END;IF regexp_replace(a,U&'[\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF]',' ','g')~*'@|https?://|(\+?[0-9][ ().-]*){9,}'THEN RAISE EXCEPTION 'Use an alias' USING ERRCODE='22023';END IF;END IF;
 IF k='pipeline_contact'AND d->>'status'<>'to_contact'AND(d->'reportedOn'='null'::jsonb OR firstten_private.guest_growth_trim(d->>'statusBasis')='')THEN RAISE EXCEPTION 'Reported status needs basis' USING ERRCODE='22023';END IF;
 IF k IN('survey','onboarding')THEN
  IF(SELECT count(*)<>count(DISTINCT x->>'id')FROM jsonb_array_elements(d->'questions')x)THEN RAISE EXCEPTION 'Duplicate questions' USING ERRCODE='22023';END IF;
  IF k='survey'THEN FOR q IN SELECT value FROM jsonb_array_elements(d->'questions')WHERE value->>'format'='single_choice'LOOP
   IF(SELECT count(*)<>count(DISTINCT firstten_private.guest_growth_option_key(value))OR bool_or(firstten_private.guest_growth_trim(value)='')FROM jsonb_array_elements_text(q->'options'))THEN RAISE EXCEPTION 'Invalid options' USING ERRCODE='22023';END IF;
  END LOOP;END IF;
 END IF;
 refs:=firstten_private.guest_growth_refs(d);IF(SELECT count(*)<>count(DISTINCT x->>'artifactId')FROM jsonb_array_elements(refs)x)THEN RAISE EXCEPTION 'Duplicate source' USING ERRCODE='22023';END IF;RETURN d;
END $$;
CREATE FUNCTION firstten_private.guest_growth_ref_manifest(d jsonb)RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT coalesce(jsonb_agg(x ORDER BY x->>'artifactId'),'[]'::jsonb)FROM jsonb_array_elements(firstten_private.guest_growth_refs(d))x$$;
CREATE TABLE firstten_private.guest_growth_artifacts(
 id uuid PRIMARY KEY,class_id uuid NOT NULL,team_id uuid NOT NULL,author_principal_id uuid NOT NULL,
 kind text NOT NULL CHECK(kind IN('learning','experiment','pipeline_contact','survey','referral','onboarding')),
 audience text NOT NULL CHECK(audience IN('principal_private','team_shared')),current_revision integer NOT NULL CHECK(current_revision BETWEEN 1 AND 40),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(id,kind),
 FOREIGN KEY(author_principal_id,class_id,team_id)REFERENCES public.class_guest_principals(id,class_id,team_id)ON DELETE CASCADE
);
CREATE TABLE firstten_private.guest_growth_versions(
 artifact_id uuid NOT NULL REFERENCES firstten_private.guest_growth_artifacts(id)ON DELETE CASCADE,revision integer NOT NULL CHECK(revision BETWEEN 1 AND 40),
 document jsonb NOT NULL CHECK(document=firstten_private.normalize_guest_growth(document)),saved_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 stored_bytes integer GENERATED ALWAYS AS(octet_length(document::text))STORED,
 reference_count integer GENERATED ALWAYS AS(jsonb_array_length(firstten_private.guest_growth_refs(document)))STORED,
 reference_digest text GENERATED ALWAYS AS(firstten_private.guest_growth_hash(firstten_private.guest_growth_ref_manifest(document)))STORED,PRIMARY KEY(artifact_id,revision)
);
ALTER TABLE firstten_private.guest_growth_artifacts ADD CONSTRAINT guest_growth_current_version FOREIGN KEY(id,current_revision)REFERENCES firstten_private.guest_growth_versions(artifact_id,revision)DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE firstten_private.guest_growth_reference_edges(
 artifact_id uuid NOT NULL,revision integer NOT NULL,source_id uuid NOT NULL,source_revision integer NOT NULL,source_kind text NOT NULL,
 PRIMARY KEY(artifact_id,revision,source_id),FOREIGN KEY(artifact_id,revision)REFERENCES firstten_private.guest_growth_versions(artifact_id,revision)ON DELETE CASCADE,
 FOREIGN KEY(source_id,source_revision)REFERENCES firstten_private.guest_growth_versions(artifact_id,revision)ON DELETE CASCADE,
 FOREIGN KEY(source_id,source_kind)REFERENCES firstten_private.guest_growth_artifacts(id,kind)ON DELETE CASCADE
);
CREATE TABLE firstten_private.guest_growth_operations(
 principal_id uuid NOT NULL REFERENCES public.class_guest_principals(id)ON DELETE CASCADE,request_id uuid NOT NULL,
 payload_hash text NOT NULL CHECK(payload_hash~'^[a-f0-9]{64}$'),artifact_id uuid NOT NULL,saved_revision integer NOT NULL,
 PRIMARY KEY(principal_id,request_id),FOREIGN KEY(artifact_id,saved_revision)REFERENCES firstten_private.guest_growth_versions(artifact_id,revision)ON DELETE CASCADE
);
CREATE INDEX guest_growth_scope ON firstten_private.guest_growth_artifacts(class_id,team_id,id);
CREATE INDEX guest_growth_private ON firstten_private.guest_growth_artifacts(author_principal_id,id)WHERE audience='principal_private';
CREATE INDEX guest_growth_source ON firstten_private.guest_growth_reference_edges(source_id,source_revision);
CREATE FUNCTION firstten_private.guest_growth_immutable()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF TG_TABLE_NAME<>'guest_growth_artifacts'THEN RAISE EXCEPTION 'Immutable growth record' USING ERRCODE='42501';END IF;
 IF(to_jsonb(NEW)-'current_revision')IS DISTINCT FROM(to_jsonb(OLD)-'current_revision')OR NEW.current_revision<>OLD.current_revision+1 THEN RAISE EXCEPTION 'Immutable growth scope/revision' USING ERRCODE='42501';END IF;RETURN NEW;
END $$;
CREATE TRIGGER guest_growth_artifact_identity BEFORE UPDATE ON firstten_private.guest_growth_artifacts FOR EACH ROW EXECUTE FUNCTION firstten_private.guest_growth_immutable();
CREATE TRIGGER guest_growth_version_identity BEFORE UPDATE ON firstten_private.guest_growth_versions FOR EACH ROW EXECUTE FUNCTION firstten_private.guest_growth_immutable();
CREATE TRIGGER guest_growth_edge_identity BEFORE UPDATE ON firstten_private.guest_growth_reference_edges FOR EACH ROW EXECUTE FUNCTION firstten_private.guest_growth_immutable();
CREATE TRIGGER guest_growth_receipt_identity BEFORE UPDATE ON firstten_private.guest_growth_operations FOR EACH ROW EXECUTE FUNCTION firstten_private.guest_growth_immutable();
DO $$DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['guest_growth_artifacts','guest_growth_versions','guest_growth_reference_edges','guest_growth_operations']LOOP EXECUTE format('ALTER TABLE firstten_private.%I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('REVOKE ALL ON firstten_private.%I FROM PUBLIC,anon,authenticated,service_role',n);END LOOP;END $$;
CREATE FUNCTION firstten_private.guest_growth_access(a firstten_private.guest_growth_artifacts,p public.class_guest_principals)RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT a.id IS NOT NULL AND a.class_id=p.class_id AND a.team_id=p.team_id AND(a.audience='team_shared'OR a.author_principal_id=p.id)$$;
CREATE FUNCTION firstten_private.guest_growth_utf16(t text)RETURNS bigint LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT coalesce(sum(CASE WHEN ascii(c)>65535 THEN 2 ELSE 1 END),0)FROM unnest(string_to_array(t,NULL))c$$;
CREATE FUNCTION firstten_private.guest_growth_authority(p public.class_guest_principals)RETURNS jsonb LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog AS $$
DECLARE c public.classes;t public.class_teams;g public.class_guest_principals;r jsonb;
BEGIN
 SELECT live_class.* INTO c FROM public.classes AS live_class WHERE live_class.id=p.class_id AND live_class.archived_at IS NULL AND live_class.access_expires_at>clock_timestamp()AND EXISTS(SELECT 1 FROM auth.users AS owner_user WHERE owner_user.id=live_class.user_id);
 SELECT live_team.* INTO t FROM public.class_teams AS live_team WHERE live_team.id=p.team_id AND live_team.class_id=p.class_id AND live_team.archived_at IS NULL;
 SELECT live_principal.* INTO g FROM public.class_guest_principals AS live_principal WHERE live_principal.id=p.id AND live_principal.class_id=p.class_id AND live_principal.team_id=p.team_id AND live_principal.revoked_at IS NULL;
 IF c.id IS NULL OR t.id IS NULL OR g.id IS NULL THEN RETURN NULL;END IF;
 IF firstten_private.guest_growth_utf16(c.name)>120 OR firstten_private.guest_growth_utf16(t.alias)>80 OR firstten_private.guest_growth_utf16(g.alias)>80 THEN RETURN NULL;END IF;
 r:=jsonb_build_object('classId',c.id,'teamId',t.id,'principalId',g.id,'className',c.name,'teamAlias',t.alias,'principalAlias',g.alias,'accessExpiresAt',c.access_expires_at,'classRevision',c.revision,'teamGeneration',t.access_revision,'principalGeneration',g.access_revision);
 IF octet_length(jsonb_build_object('ok',true,'data',r)::text)>4096 THEN RETURN NULL;END IF;RETURN r;
END $$;
CREATE FUNCTION firstten_private.guest_growth_finish(p_session text,p public.class_guest_principals,authority jsonb)RETURNS void LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog AS $$
BEGIN IF(firstten_private.resolve_guest(p_session)).id IS DISTINCT FROM p.id OR firstten_private.guest_growth_authority(p)IS DISTINCT FROM authority OR authority IS NULL THEN RAISE EXCEPTION 'Guest scope expired or changed' USING ERRCODE='PGX02';END IF;END $$;
-- Validate and lock only metadata/retained sources in the real namespace; never copy linked bodies.
CREATE FUNCTION firstten_private.guest_growth_lineage(p public.class_guest_principals,a firstten_private.guest_growth_artifacts,r integer)RETURNS boolean LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog AS $$
DECLARE s record;depth integer;total integer;
BEGIN
 IF NOT firstten_private.guest_growth_access(a,p)OR NOT EXISTS(SELECT 1 FROM firstten_private.guest_growth_versions WHERE artifact_id=a.id AND revision=r)THEN RETURN false;END IF;
 SELECT max(n),count(*)INTO depth,total FROM(WITH RECURSIVE tree(id,rev,n)AS(SELECT a.id,r,0 UNION SELECT e.source_id,e.source_revision,t.n+1 FROM tree t JOIN firstten_private.guest_growth_reference_edges e ON e.artifact_id=t.id AND e.revision=t.rev WHERE t.n<4)SELECT DISTINCT id,rev,n FROM tree)x;
 IF depth>3 OR total>32 THEN RETURN false;END IF;
 FOR s IN WITH RECURSIVE tree(id,rev)AS(SELECT a.id,r UNION SELECT e.source_id,e.source_revision FROM tree t JOIN firstten_private.guest_growth_reference_edges e ON e.artifact_id=t.id AND e.revision=t.rev)SELECT DISTINCT id,rev FROM tree ORDER BY id,rev LOOP
  PERFORM 1 FROM firstten_private.guest_growth_artifacts x JOIN firstten_private.guest_growth_versions v ON v.artifact_id=x.id AND v.revision=s.rev WHERE x.id=s.id AND firstten_private.guest_growth_access(x,p)AND(a.audience='principal_private'OR x.audience='team_shared')FOR SHARE OF x,v;
  IF NOT FOUND THEN RETURN false;END IF;
  IF EXISTS(SELECT 1 FROM firstten_private.guest_growth_versions v WHERE v.artifact_id=s.id AND v.revision=s.rev AND
   (v.reference_count<>(SELECT count(*)FROM firstten_private.guest_growth_reference_edges e WHERE e.artifact_id=s.id AND e.revision=s.rev)OR
    v.reference_digest<>(SELECT encode(sha256(convert_to(firstten_private.guest_growth_json(coalesce(jsonb_agg(jsonb_build_object('kind',e.source_kind,'artifactId',e.source_id,'revision',e.source_revision)ORDER BY e.source_id),'[]'::jsonb)),'UTF8')),'hex')FROM firstten_private.guest_growth_reference_edges e WHERE e.artifact_id=s.id AND e.revision=s.rev)))THEN RETURN false;END IF;
 END LOOP;RETURN true;
END $$;
CREATE FUNCTION firstten_private.guest_growth_record(a firstten_private.guest_growth_artifacts,r integer,include_document boolean DEFAULT true)RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$SELECT jsonb_build_object('id',a.id,'classId',a.class_id,'teamId',a.team_id,'authorPrincipalId',a.author_principal_id,'audience',a.audience,'kind',a.kind,'revision',v.revision,'savedAt',v.saved_at,'aiEnabled',false)||CASE WHEN include_document THEN jsonb_build_object('document',v.document)ELSE'{}'::jsonb END FROM firstten_private.guest_growth_versions v WHERE v.artifact_id=a.id AND v.revision=r$$;
CREATE FUNCTION public.get_guest_growth_authority(p_session text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET lock_timeout='5s' AS $$
DECLARE p public.class_guest_principals;authority jsonb;
BEGIN
 p:=firstten_private.lock_guest_learning(p_session);IF p.id IS NULL THEN RETURN jsonb_build_object('ok',false,'code','NOT_FOUND');END IF;
 authority:=firstten_private.guest_growth_authority(p);PERFORM firstten_private.guest_growth_finish(p_session,p,authority);RETURN jsonb_build_object('ok',true,'data',authority);
EXCEPTION WHEN SQLSTATE'PGX02'THEN RETURN jsonb_build_object('ok',false,'code','NOT_FOUND');END $$;
CREATE FUNCTION public.list_guest_growth_artifacts(p_session text,p_kind text DEFAULT NULL,p_cursor uuid DEFAULT NULL)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET lock_timeout='5s' AS $$
DECLARE p public.class_guest_principals;authority jsonb;items jsonb;next_id uuid;n integer;
BEGIN
 p:=firstten_private.lock_guest_learning(p_session);IF p.id IS NULL THEN RETURN jsonb_build_object('ok',false,'code','NOT_FOUND');END IF;
 IF NOT firstten_private.guest_learning_rate(p.id)THEN RETURN jsonb_build_object('ok',false,'code','RATE_LIMITED');END IF;authority:=firstten_private.guest_growth_authority(p);
 IF p_kind IS NOT NULL AND NOT firstten_private.guest_growth_shapes()?p_kind THEN RETURN jsonb_build_object('ok',false,'code','INVALID_INPUT');END IF;
 WITH candidates AS(SELECT a AS artifact FROM firstten_private.guest_growth_artifacts a WHERE a.class_id=p.class_id AND a.team_id=p.team_id AND firstten_private.guest_growth_access(a,p)AND(p_kind IS NULL OR a.kind=p_kind)AND(p_cursor IS NULL OR a.id>p_cursor)AND firstten_private.guest_growth_lineage(p,a,a.current_revision)ORDER BY a.id LIMIT 51),page AS(SELECT artifact FROM candidates ORDER BY(artifact).id LIMIT 50)
 SELECT coalesce((SELECT jsonb_agg(firstten_private.guest_growth_record(a.artifact,(a.artifact).current_revision,false)ORDER BY(a.artifact).id)FROM page a),'[]'::jsonb),(SELECT count(*)FROM candidates),(SELECT(artifact).id FROM page ORDER BY(artifact).id DESC LIMIT 1)INTO items,n,next_id;
 PERFORM firstten_private.guest_growth_finish(p_session,p,authority);RETURN jsonb_build_object('ok',true,'data',jsonb_build_object('items',items,'nextCursor',CASE WHEN n>50 THEN next_id ELSE NULL END));
EXCEPTION WHEN SQLSTATE'PGX02'THEN RETURN jsonb_build_object('ok',false,'code','NOT_FOUND');END $$;
CREATE FUNCTION public.load_guest_growth_artifact(p_session text,p_artifact_id uuid,p_revision integer DEFAULT NULL)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET lock_timeout='5s' AS $$
DECLARE p public.class_guest_principals;authority jsonb;a firstten_private.guest_growth_artifacts;r integer;result jsonb;
BEGIN
 p:=firstten_private.lock_guest_learning(p_session);IF p.id IS NULL THEN RETURN jsonb_build_object('ok',false,'code','NOT_FOUND');END IF;
 IF NOT firstten_private.guest_learning_rate(p.id)THEN RETURN jsonb_build_object('ok',false,'code','RATE_LIMITED');END IF;authority:=firstten_private.guest_growth_authority(p);
 IF p_artifact_id IS NULL OR(p_revision IS NOT NULL AND p_revision NOT BETWEEN 1 AND 40)THEN RETURN jsonb_build_object('ok',false,'code','INVALID_INPUT');END IF;
 SELECT * INTO a FROM firstten_private.guest_growth_artifacts WHERE id=p_artifact_id FOR SHARE;r:=coalesce(p_revision,a.current_revision);
 IF NOT firstten_private.guest_growth_access(a,p)OR NOT firstten_private.guest_growth_lineage(p,a,r)THEN RETURN jsonb_build_object('ok',false,'code','NOT_FOUND');END IF;
 result:=firstten_private.guest_growth_record(a,r);PERFORM firstten_private.guest_growth_finish(p_session,p,authority);RETURN jsonb_build_object('ok',true,'data',result);
EXCEPTION WHEN SQLSTATE'PGX02'THEN RETURN jsonb_build_object('ok',false,'code','NOT_FOUND');END $$;
CREATE FUNCTION public.get_guest_growth_history(p_session text,p_artifact_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET lock_timeout='5s' AS $$
DECLARE p public.class_guest_principals;authority jsonb;a firstten_private.guest_growth_artifacts;items jsonb;
BEGIN
 p:=firstten_private.lock_guest_learning(p_session);IF p.id IS NULL THEN RETURN jsonb_build_object('ok',false,'code','NOT_FOUND');END IF;
 IF NOT firstten_private.guest_learning_rate(p.id)THEN RETURN jsonb_build_object('ok',false,'code','RATE_LIMITED');END IF;authority:=firstten_private.guest_growth_authority(p);
 SELECT * INTO a FROM firstten_private.guest_growth_artifacts WHERE id=p_artifact_id FOR SHARE;IF NOT firstten_private.guest_growth_access(a,p)THEN RETURN jsonb_build_object('ok',false,'code','NOT_FOUND');END IF;
 SELECT coalesce(jsonb_agg(firstten_private.guest_growth_record(a,v.revision,false)ORDER BY v.revision DESC),'[]'::jsonb)INTO items FROM firstten_private.guest_growth_versions v WHERE v.artifact_id=a.id AND firstten_private.guest_growth_lineage(p,a,v.revision);
 IF jsonb_array_length(items)=0 THEN RETURN jsonb_build_object('ok',false,'code','NOT_FOUND');END IF;PERFORM firstten_private.guest_growth_finish(p_session,p,authority);RETURN jsonb_build_object('ok',true,'data',jsonb_build_object('artifactId',a.id,'versions',items));
EXCEPTION WHEN SQLSTATE'PGX02'THEN RETURN jsonb_build_object('ok',false,'code','NOT_FOUND');END $$;
CREATE FUNCTION firstten_private.guest_growth_version_kind()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN IF NOT EXISTS(SELECT 1 FROM firstten_private.guest_growth_artifacts WHERE id=NEW.artifact_id AND kind=NEW.document->>'kind')THEN RAISE EXCEPTION 'Version kind mismatch' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER guest_growth_version_kind BEFORE INSERT ON firstten_private.guest_growth_versions FOR EACH ROW EXECUTE FUNCTION firstten_private.guest_growth_version_kind();
CREATE FUNCTION firstten_private.guest_growth_edge_scope()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE a firstten_private.guest_growth_artifacts;b firstten_private.guest_growth_artifacts;d jsonb;
BEGIN
 SELECT * INTO a FROM firstten_private.guest_growth_artifacts WHERE id=NEW.artifact_id;SELECT * INTO b FROM firstten_private.guest_growth_artifacts WHERE id=NEW.source_id;
 SELECT document INTO d FROM firstten_private.guest_growth_versions WHERE artifact_id=a.id AND revision=NEW.revision;
 IF a.class_id<>b.class_id OR a.team_id<>b.team_id OR(a.audience='team_shared'AND b.audience<>'team_shared')OR(b.audience='principal_private'AND a.author_principal_id<>b.author_principal_id)
 OR NOT((a.kind='experiment'AND b.kind='learning')OR(a.kind IN('survey','onboarding')AND b.kind='experiment')OR(a.kind='referral'AND b.kind IN('pipeline_contact','experiment')))
 OR NOT firstten_private.guest_growth_refs(d)@>jsonb_build_array(jsonb_build_object('kind',NEW.source_kind,'artifactId',NEW.source_id,'revision',NEW.source_revision))THEN RAISE EXCEPTION 'Invalid retained source edge' USING ERRCODE='23514';END IF;RETURN NEW;
END $$;
CREATE TRIGGER guest_growth_edge_scope BEFORE INSERT ON firstten_private.guest_growth_reference_edges FOR EACH ROW EXECUTE FUNCTION firstten_private.guest_growth_edge_scope();
-- Deferred checks run after the service RPC returns; retain trusted trigger-only authority.
CREATE FUNCTION firstten_private.guest_growth_edges_complete()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN IF EXISTS(SELECT 1 FROM firstten_private.guest_growth_versions WHERE artifact_id=NEW.artifact_id AND revision=NEW.revision)AND
 (SELECT count(*)FROM firstten_private.guest_growth_reference_edges WHERE artifact_id=NEW.artifact_id AND revision=NEW.revision)<>jsonb_array_length(firstten_private.guest_growth_refs(NEW.document))THEN RAISE EXCEPTION 'Retained source edges incomplete' USING ERRCODE='23514';END IF;RETURN NULL;END $$;
ALTER FUNCTION firstten_private.guest_growth_edges_complete()OWNER TO postgres;
CREATE CONSTRAINT TRIGGER guest_growth_edges_complete AFTER INSERT ON firstten_private.guest_growth_versions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION firstten_private.guest_growth_edges_complete();
CREATE FUNCTION public.save_guest_growth_artifact(p_session text,p_artifact_id uuid,p_audience text,p_expected_revision bigint,p_mutation_id uuid,p_shared_confirmed boolean,p_document jsonb)RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET lock_timeout='5s' AS $$
DECLARE p public.class_guest_principals;a firstten_private.guest_growth_artifacts;b firstten_private.guest_growth_artifacts;op firstten_private.guest_growth_operations;
 authority jsonb;d jsonb;hash text;r jsonb;n integer;size integer;private_bytes bigint;team_bytes bigint;class_bytes bigint;result jsonb;
BEGIN
 p:=firstten_private.lock_guest_learning(p_session);IF p.id IS NULL THEN RETURN jsonb_build_object('ok',false,'code','NOT_FOUND');END IF;
 IF NOT firstten_private.guest_learning_rate(p.id)THEN RETURN jsonb_build_object('ok',false,'code','RATE_LIMITED');END IF;authority:=firstten_private.guest_growth_authority(p);
 IF p_artifact_id IS NULL OR p_mutation_id IS NULL OR p_audience IS NULL OR p_audience NOT IN('principal_private','team_shared')OR p_expected_revision IS NULL OR p_expected_revision NOT BETWEEN 0 AND 39 OR p_shared_confirmed IS NULL THEN RETURN jsonb_build_object('ok',false,'code','INVALID_INPUT');END IF;
 d:=firstten_private.normalize_guest_growth(p_document);
 hash:=encode(sha256(convert_to(jsonb_build_object('artifact',p_artifact_id,'audience',p_audience,'expectedRevision',p_expected_revision,'sharedConfirmed',p_shared_confirmed,'document',d)::text,'UTF8')),'hex');
 SELECT * INTO op FROM firstten_private.guest_growth_operations WHERE principal_id=p.id AND request_id=p_mutation_id;
 SELECT * INTO a FROM firstten_private.guest_growth_artifacts WHERE id=p_artifact_id FOR UPDATE;
 IF a.id IS NOT NULL AND(NOT firstten_private.guest_growth_access(a,p)OR a.audience<>p_audience OR a.kind<>d->>'kind')THEN RETURN jsonb_build_object('ok',false,'code','NOT_FOUND');END IF;
 IF op.request_id IS NOT NULL THEN
  IF op.payload_hash<>hash OR op.artifact_id<>p_artifact_id THEN RETURN jsonb_build_object('ok',false,'code','IDEMPOTENCY_CONFLICT');END IF;
  IF NOT firstten_private.guest_growth_access(a,p)OR NOT firstten_private.guest_growth_lineage(p,a,a.current_revision)OR NOT firstten_private.guest_growth_lineage(p,a,op.saved_revision)THEN RETURN jsonb_build_object('ok',false,'code','NOT_FOUND');END IF;
  result:=jsonb_build_object('ok',true,'data',jsonb_build_object('record',firstten_private.guest_growth_record(a,a.current_revision),'savedRevision',op.saved_revision,'replayed',true));PERFORM firstten_private.guest_growth_finish(p_session,p,authority);RETURN result;
 END IF;
 IF coalesce(a.current_revision,0)<>p_expected_revision THEN RETURN jsonb_build_object('ok',false,'code','CONFLICT','currentRevision',coalesce(a.current_revision,0));END IF;
 IF coalesce(a.current_revision,0)>=40 OR(SELECT count(*)FROM firstten_private.guest_growth_operations WHERE principal_id=p.id)>=2000 THEN RETURN jsonb_build_object('ok',false,'code','CAPACITY');END IF;
 IF a.id IS NULL THEN
  IF p_audience='team_shared'AND(p_shared_confirmed IS DISTINCT FROM true OR d<>jsonb_set(firstten_private.guest_growth_blank(d->>'kind'),'{stage}',d->'stage'))THEN RETURN jsonb_build_object('ok',false,'code','INVALID_INPUT');END IF;
  IF(p_audience='principal_private'AND(SELECT count(*)FROM firstten_private.guest_growth_artifacts WHERE author_principal_id=p.id AND audience='principal_private')>=64)
   OR(p_audience='team_shared'AND(SELECT count(*)FROM firstten_private.guest_growth_artifacts WHERE team_id=p.team_id AND audience='team_shared')>=96)THEN RETURN jsonb_build_object('ok',false,'code','CAPACITY');END IF;
 END IF;
 -- Every declared exact source is real, current-access eligible and transitively bounded.
 FOR r IN SELECT value FROM jsonb_array_elements(firstten_private.guest_growth_refs(d))ORDER BY value->>'artifactId'LOOP
  SELECT * INTO b FROM firstten_private.guest_growth_artifacts WHERE id=(r->>'artifactId')::uuid FOR SHARE;
  IF NOT firstten_private.guest_growth_access(b,p)OR b.kind<>r->>'kind'OR(p_audience='team_shared'AND b.audience<>'team_shared')OR NOT firstten_private.guest_growth_lineage(p,b,(r->>'revision')::integer)THEN RETURN jsonb_build_object('ok',false,'code','NOT_FOUND');END IF;
 END LOOP;
 size:=octet_length(d::text);
 SELECT coalesce(sum(v.stored_bytes)FILTER(WHERE x.audience='principal_private'AND x.author_principal_id=p.id),0),coalesce(sum(v.stored_bytes)FILTER(WHERE x.audience='team_shared'AND x.team_id=p.team_id),0),coalesce(sum(v.stored_bytes),0)INTO private_bytes,team_bytes,class_bytes FROM firstten_private.guest_growth_versions v JOIN firstten_private.guest_growth_artifacts x ON x.id=v.artifact_id WHERE x.class_id=p.class_id;
 IF class_bytes+size>33554432 OR(p_audience='principal_private'AND private_bytes+size>2097152)OR(p_audience='team_shared'AND team_bytes+size>8388608)THEN RETURN jsonb_build_object('ok',false,'code','CAPACITY');END IF;
 IF a.id IS NULL THEN INSERT INTO firstten_private.guest_growth_artifacts(id,class_id,team_id,author_principal_id,kind,audience,current_revision)VALUES(p_artifact_id,p.class_id,p.team_id,p.id,d->>'kind',p_audience,1)RETURNING * INTO a;
 ELSE UPDATE firstten_private.guest_growth_artifacts SET current_revision=current_revision+1 WHERE id=a.id RETURNING * INTO a;END IF;
 INSERT INTO firstten_private.guest_growth_versions(artifact_id,revision,document)VALUES(a.id,a.current_revision,d);
 INSERT INTO firstten_private.guest_growth_reference_edges(artifact_id,revision,source_id,source_revision,source_kind)SELECT a.id,a.current_revision,(x->>'artifactId')::uuid,(x->>'revision')::integer,x->>'kind'FROM jsonb_array_elements(firstten_private.guest_growth_refs(d))x;
 IF NOT firstten_private.guest_growth_lineage(p,a,a.current_revision)THEN RAISE EXCEPTION 'Invalid growth lineage' USING ERRCODE='PGX02';END IF;
 INSERT INTO firstten_private.guest_growth_operations(principal_id,request_id,payload_hash,artifact_id,saved_revision)VALUES(p.id,p_mutation_id,hash,a.id,a.current_revision);
 result:=jsonb_build_object('ok',true,'data',jsonb_build_object('record',firstten_private.guest_growth_record(a,a.current_revision),'savedRevision',a.current_revision,'replayed',false));
 PERFORM firstten_private.guest_growth_finish(p_session,p,authority);RETURN result;
EXCEPTION WHEN SQLSTATE'PGX02'THEN RETURN jsonb_build_object('ok',false,'code','NOT_FOUND');WHEN invalid_parameter_value OR invalid_text_representation OR check_violation OR numeric_value_out_of_range OR datetime_field_overflow OR invalid_datetime_format THEN RETURN jsonb_build_object('ok',false,'code','INVALID_INPUT');END $$;
-- One bounded rate attempt per complete exact-source export check. No source bodies leave this RPC.
CREATE FUNCTION public.authorize_guest_growth_export(p_session text,p_scope jsonb,p_sources jsonb)RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET lock_timeout='5s' AS $$
DECLARE p public.class_guest_principals;authority jsonb;expected jsonb;s jsonb;d jsonb;a firstten_private.guest_growth_artifacts;record jsonb;keys text[]:='{}';key text;shape jsonb;
BEGIN
 p:=firstten_private.lock_guest_learning(p_session);IF p.id IS NULL THEN RETURN jsonb_build_object('ok',false,'code','NOT_FOUND');END IF;
 IF NOT firstten_private.guest_learning_rate(p.id)THEN RETURN jsonb_build_object('ok',false,'code','RATE_LIMITED');END IF;
 authority:=firstten_private.guest_growth_authority(p);PERFORM firstten_private.guest_growth_finish(p_session,p,authority);
 IF p_sources IS NULL OR jsonb_typeof(p_sources)<>'array'OR jsonb_array_length(p_sources)NOT BETWEEN 1 AND 50 OR octet_length(coalesce(p_scope::text,'')||p_sources::text)>65536 THEN RETURN jsonb_build_object('ok',false,'code','INVALID_INPUT');END IF;
 expected:=jsonb_build_object('classId',p.class_id,'teamId',p.team_id,'principalId',p.id,'accessExpiresAt',authority->'accessExpiresAt','contextHash',encode(sha256(convert_to(firstten_private.guest_growth_json(authority-ARRAY['classRevision','teamGeneration','principalGeneration']),'UTF8')),'hex'));
 IF p_scope IS DISTINCT FROM expected THEN RETURN jsonb_build_object('ok',false,'code','CHANGED');END IF;
 FOR s IN SELECT value FROM jsonb_array_elements(p_sources)LOOP
  IF s->>'state'='draft'THEN
   shape:='{"type":"object","properties":{"state":{"const":"draft"},"localDraftId":{"type":"string","format":"uuid"},"kind":{"type":"string","enum":["learning","experiment","pipeline_contact","survey","referral","onboarding"]}}}'::jsonb;
   d:=firstten_private.guest_growth_field(s,shape);key:='draft:'||(d->>'localDraftId');
  ELSE
   shape:='{"type":"object","properties":{"state":{"const":"saved"},"artifactId":{"type":"string","format":"uuid"},"revision":{"type":"integer","minimum":1,"maximum":40},"kind":{"type":"string","enum":["learning","experiment","pipeline_contact","survey","referral","onboarding"]},"audience":{"type":"string","enum":["principal_private","team_shared"]},"authorPrincipalId":{"type":"string","format":"uuid"},"recordHash":{"type":"string","maxLength":64}}}'::jsonb;
   d:=firstten_private.guest_growth_field(s,shape);key:='saved:'||(d->>'artifactId')||':'||(d->>'revision');
   IF d->>'recordHash'!~'^[a-f0-9]{64}$'THEN RETURN jsonb_build_object('ok',false,'code','INVALID_INPUT');END IF;
   SELECT * INTO a FROM firstten_private.guest_growth_artifacts WHERE id=(d->>'artifactId')::uuid FOR SHARE;
   IF NOT firstten_private.guest_growth_access(a,p)OR a.kind<>d->>'kind'OR a.audience<>d->>'audience'OR a.author_principal_id<>(d->>'authorPrincipalId')::uuid OR NOT firstten_private.guest_growth_lineage(p,a,(d->>'revision')::integer)THEN RETURN jsonb_build_object('ok',false,'code','CHANGED');END IF;
   record:=firstten_private.guest_growth_record(a,(d->>'revision')::integer);
   IF encode(sha256(convert_to(firstten_private.guest_growth_json(record),'UTF8')),'hex')<>d->>'recordHash'THEN RETURN jsonb_build_object('ok',false,'code','CHANGED');END IF;
  END IF;
  IF key=ANY(keys)THEN RETURN jsonb_build_object('ok',false,'code','INVALID_INPUT');END IF;keys:=array_append(keys,key);
 END LOOP;
 PERFORM firstten_private.guest_growth_finish(p_session,p,authority);RETURN jsonb_build_object('ok',true);
EXCEPTION WHEN SQLSTATE'PGX02'THEN RETURN jsonb_build_object('ok',false,'code','NOT_FOUND');WHEN invalid_parameter_value OR invalid_text_representation OR check_violation OR numeric_value_out_of_range THEN RETURN jsonb_build_object('ok',false,'code','INVALID_INPUT');END $$;
DO $$DECLARE r record;BEGIN FOR r IN SELECT p.oid::regprocedure signature,n.nspname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE(n.nspname='firstten_private'AND(p.proname LIKE'guest_growth_%'OR p.proname='normalize_guest_growth'))OR(n.nspname='public'AND p.proname IN('authorize_guest_growth_export','get_guest_growth_authority','list_guest_growth_artifacts','load_guest_growth_artifact','get_guest_growth_history','save_guest_growth_artifact'))LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,service_role',r.signature);IF r.nspname='public'THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',r.signature);END IF;END LOOP;END $$;
COMMENT ON TABLE firstten_private.guest_growth_versions IS 'Immutable genuine-guest authored drafts and reported outcomes; no customer proof, AI permission or teacher access. Exact retained revisions and references remain bounded until parent class/account deletion. Access expiry does not promise automatic deletion.';
COMMIT;
